param([switch]$Installer)

$ErrorActionPreference = 'Stop'

# VERSION is the single source of the product version (major.minor.patch).
$version = (Get-Content -LiteralPath (Join-Path $PSScriptRoot 'VERSION') -TotalCount 1).Trim()
if ($version -notmatch '^(\d{1,3})\.(\d{1,3})\.(\d{1,5})$') { throw "VERSION must look like 1.2.3 (found '$version')." }
$parts = $version.Split('.')
$buildDir = Join-Path $PSScriptRoot 'build'
New-Item -ItemType Directory -Force $buildDir | Out-Null
$header = @"
// Generated by build.ps1 from VERSION. Do not edit.
#pragma once
#define STLQV_VERSION_COMMA $($parts[0]),$($parts[1]),$($parts[2]),0
#define STLQV_VERSION_STR "$version"
#define STLQV_VERSION_WSTR L"$version"
"@
Set-Content -LiteralPath (Join-Path $buildDir 'version.h') -Value $header -Encoding ascii

$vswhere = Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe'
$vs = & $vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
if (-not $vs) { throw 'Install the Visual Studio C++ build tools and Windows SDK.' }
$env:STLQV_VCVARS = Join-Path $vs 'VC\Auxiliary\Build\vcvars64.bat'
Push-Location $PSScriptRoot
try {
    $target = if ($Installer) { 'installer' } else { 'portable' }
    & cmd.exe /d /c .\build.cmd $target
    if ($LASTEXITCODE -ne 0) { throw "Build failed ($LASTEXITCODE)." }
} finally {
    Pop-Location
    Remove-Item Env:STLQV_VCVARS -ErrorAction SilentlyContinue
}
Write-Host "Built STL Quick View $version"
